import { json, fail, body, id, clean, validEmail, validPhone, passwordHash, requireOrigin } from '../../_lib/core.js';
export async function onRequestPost({request,env}) { const oe=requireOrigin(request); if(oe) return oe; if(!env.ADMIN_BOOTSTRAP_TOKEN) return fail('إعداد إنشاء الأدمن غير موجود',503); const d=await body(request); const token=request.headers.get('X-Admin-Bootstrap'); if(!token||token!==env.ADMIN_BOOTSTRAP_TOKEN) return fail('غير مصرح',403); const count=await env.DB.prepare("SELECT COUNT(*) AS n FROM users WHERE role='admin'").first(); if(count?.n) return fail('تم إنشاء حساب الإدارة بالفعل',409); const name=clean(d?.full_name,100),email=clean(d?.email,180).toLowerCase(),phone=clean(d?.phone,24),password=typeof d?.password==='string'?d.password:''; if(name.split(/\s+/).length<2||!validEmail(email)||!validPhone(phone)||password.length<14) return fail('أدخل اسمًا وبريدًا وهاتفًا وكلمة مرور قوية لا تقل عن 14 حرفًا'); const uid=id(); await env.DB.prepare("INSERT INTO users(id,full_name,email,phone,password_hash,role,status) VALUES(?,?,?,?,?,'admin','active')").bind(uid,name,email,phone,await passwordHash(password)).run(); return json({ok:true,message:'تم إنشاء حساب الإدارة. احذف ADMIN_BOOTSTRAP_TOKEN من الإعدادات فورًا.'},201); }
